let vert = `
attribute vec3 aPosition;
attribute vec4 aVertexColor;
attribute vec3 aNormal;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

uniform vec3 uAmbientColor[5];
uniform vec3 uLightingDirection[5];

varying highp vec2 vVertTexCoord;
varying vec3 vLightDirection;
varying vec3 vNormal;
varying vec3 vAmbientColor;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
	vec4 viewModelPosition = uModelViewMatrix * positionVec4; 
  gl_Position = uProjectionMatrix * viewModelPosition;

	vVertTexCoord = aTexCoord;

	vNormal = normalize(uNormalMatrix * aNormal);
	vLightDirection = -uLightingDirection[0];
	vAmbientColor = uAmbientColor[0];
}
`;


let frag = `
precision highp float;

uniform vec4 uMaterialColor;
uniform sampler2D uSampler;
uniform bool isTexture;
uniform float uSeed;	

varying highp vec2 vVertTexCoord;
varying vec3 vLightDirection;
varying vec3 vNormal;
varying vec3 vAmbientColor;

float rnd(vec2 p){
	return fract(sin(dot(p ,vec2(12.9898,78.233))) * uSeed);
}

void main(void) {
	gl_FragColor = isTexture ? texture2D(uSampler, vVertTexCoord) : uMaterialColor;

	float amt = rnd(gl_FragCoord.xy/100.0);
	vec3 direction = normalize(vLightDirection);
	vec3 normal = normalize(vNormal);
	float diffuse = dot(direction, normal);

	if (diffuse < amt-0.5) {
		gl_FragColor.rgb *= vAmbientColor;
	} else if (diffuse < amt) {
		gl_FragColor.rgb *= mix(vec3(1.0), vAmbientColor, 0.5);
	}
}
`;

